import module namespace mod4="http://example.ns/module4";
declare %private type mod4:dateSupplier as element(foo);        
declare %private type mod4:timeSupplier as element(bar);
declare %private record mod4:dateTimeSupplier (d as mod4:dateSupplier, t as mod4:timeSupplier, i as (fn() as xs:integer)?);
let $provider as mod4:dateTimeSupplier := $mod4:dateTimeNow
let $dt := $provider()
let ${$date, $time} := $dt
return
{ "r1": $date() instance of xs:date,
  "r2": $time() instance of xs:time
}
